SELECT uid,version,on_hand_qty,last_ledger_sequence FROM public.inventory_balance WHERE uid='2bef84dd-3089-4827-aed0-4a3503bfda1d'::uuid;
SELECT uid,sequence,quantity_delta,reversal_of_ledger_id,command_id FROM public.inventory_ledger_entry WHERE warehouse_site_id='e1a896a1-f86a-4201-859e-4a3503bfd8a1'::uuid ORDER BY sequence;
SELECT to_jsonb(h)::text AS outbound_header FROM public.outbound_document h WHERE uid IN ('7eb59988-74c4-4178-a612-4a3503bfda4c'::uuid,'180fbf17-b579-4d3e-8282-4a3503bfda66'::uuid) ORDER BY uid;
SELECT to_jsonb(h)::text AS inbound_header FROM public.inbound_document h WHERE uid='7e10a691-191e-4593-8a01-4a3503bfd9a7'::uuid;
SELECT doc_type,year_month,current_no FROM public.document_sequence WHERE year_month='650610' OR (doc_type='PO' AND year_month='202610') OR (doc_type='CR' AND year_month='650410') ORDER BY doc_type,year_month;
SELECT last_value,is_called FROM public.inventory_ledger_sequence;
SELECT count(*) AS failed_receipt_count FROM public.command_receipt WHERE command_id IN ('9935668e-0c0c-4399-b6e2-46985bdbcc06'::uuid,'9935668e-0c0c-4399-b6e2-46985bdbcc09'::uuid);
SELECT count(*) AS remaining_competitor_connections FROM pg_stat_activity WHERE datname=current_database() AND pid IN (280,8112,7496) AND pid<>pg_backend_pid();
SELECT count(*) AS remaining_advisory_locks FROM pg_locks WHERE locktype='advisory' AND pid IN (280,8112,7496);
